from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] != 8:
                        seen.add((yy,xx)); q.append((yy,xx))
            colored = [(y,x,grid[y][x]) for y,x in cells if grid[y][x] != 0]
            if not colored:
                continue
            colors = {v for _,_,v in colored}
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            r0, r1 = min(y for y,x,v in colored), max(y for y,x,v in colored)
            c0, c1 = min(x for y,x,v in colored), max(x for y,x,v in colored)
            th, tw = r1-r0+1, c1-c0+1
            pattern = [[1 if grid[r0+i][c0+j] == color else 0 for j in range(tw)] for i in range(th)]
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            # Anchor the repeated motif at the seed's own upper-left coordinate.
            for y in range(y0, y1+1):
                for x in range(x0, x1+1):
                    out[y][x] = color if pattern[(y-r0) % th][(x-c0) % tw] else 0
    return out

